# Nodemailer Resend

> Transport for sending email via the Resend SDK

<p align="left">
  <img alt="NPM Version" src="https://img.shields.io/npm/v/%40documenso/nodemailer-resend" />
  <img alt="GitHub Repo stars" src="https://img.shields.io/github/stars/documenso/nodemailer-resend">
  <img alt="GitHub" src="https://img.shields.io/github/license/documenso/nodemailer-resend">
</p>

### Getting Started!

#### Install the package

```bash
npm install @documenso/nodemailer-resend
```

### Usage

#### Create Nodemailer Transport

```typescript
import { ResendTransport } from '@documenso/nodemailer-resend';
import { createTransport } from 'nodemailer';

const mailer = createTransport(
  createTransport(
    ResendTransport.makeTransport({
      apiKey: [REDACTED] || '',
    }),
  ),
);
```

#### Send an Email

```typescript
mailer.sendMail({
  from: 'timur@documenso.com',
  to: 'zeno@resend.com',
  subject: 'Hello from Resend!',
  html: '<h1>Hello world!</h1>',
});
```

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    testTimeout: 10_000,
  },
});

import { Stream } from 'node:stream';
import type Mail from 'nodemailer/lib/mailer';
import type MailMessage from 'nodemailer/lib/mailer/mail-message';
import { describe, expect, it, vi } from 'vitest';

import { ResendTransport } from './transport';

const sendViaTransport = async (transport: ResendTransport, mailData: Mail.Options) => {
  const sendSpy = vi.fn().mockResolvedValue({ data: { id: 'fake-id' }, error: null });

  (transport as unknown as { _client: { emails: { send: typeof sendSpy } } })._client = {
    emails: { send: sendSpy },
  };

  await new Promise<void>((resolve, reject) => {
    transport.send({ data: mailData } as unknown as MailMessage, (err) =>
      err ? reject(err) : resolve(),
    );
  });

  return sendSpy.mock.calls[0][0];
};

const BASE_MAIL_DATA: Mail.Options = {
  from: { name: 'Test User', address: 'test@example.com' },
  to: 'recipient@example.com',
  subject: 'Test subject',
  html: '<p>hi</p>',
  text: 'hi',
};

describe('ResendTransport', () => {
  describe('send', () => {
    it('should pass replyTo to the Resend API when set', async () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const payload = await sendViaTransport(transport, {
        ...BASE_MAIL_DATA,
        replyTo: 'reply@example.com',
      });

      expect(payload.replyTo).toEqual(['reply@example.com']);
    });

    it('should pass replyTo address objects to the Resend API when set', async () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const payload = await sendViaTransport(transport, {
        ...BASE_MAIL_DATA,
        replyTo: { name: 'Reply User', address: 'reply@example.com' },
      });

      expect(payload.replyTo).toEqual(['reply@example.com']);
    });

    it('should omit replyTo when it is not set', async () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const payload = await sendViaTransport(transport, BASE_MAIL_DATA);

      expect(payload.replyTo).toBeUndefined();
    });

    it('should pass custom headers to the Resend API when set', async () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const payload = await sendViaTransport(transport, {
        ...BASE_MAIL_DATA,
        headers: {
          'X-Custom-Header': 'custom-value',
          'X-Other-Header': 'other-value',
        },
      });

      expect(payload.headers).toEqual({
        'X-Custom-Header': 'custom-value',
        'X-Other-Header': 'other-value',
      });
    });

    it('should omit headers when they are not set', async () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const payload = await sendViaTransport(transport, BASE_MAIL_DATA);

      expect(payload.headers).toBeUndefined();
    });
  });

  describe('toResendHeaders', () => {
    it('should return undefined when headers are not set', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const result = transport.toResendHeaders(undefined);

      expect(result).toBeUndefined();
    });

    it('should return undefined when headers are empty', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const result = transport.toResendHeaders({});

      expect(result).toBeUndefined();
    });

    it('should pass through string values', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const result = transport.toResendHeaders({ 'X-Test': 'value' });

      expect(result).toEqual({ 'X-Test': 'value' });
    });

    it('should join array values with a comma', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const result = transport.toResendHeaders({ 'X-Test': ['a', 'b'] });

      expect(result).toEqual({ 'X-Test': 'a, b' });
    });

    it('should unwrap prepared header values', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const result = transport.toResendHeaders({ 'X-Test': { prepared: true, value: 'value' } });

      expect(result).toEqual({ 'X-Test': 'value' });
    });

    it('should convert key-value entry arrays and combine duplicate keys', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const result = transport.toResendHeaders([
        { key: 'X-Test', value: 'a' },
        { key: 'X-Test', value: 'b' },
        { key: 'X-Other', value: 'c' },
      ]);

      expect(result).toEqual({ 'X-Test': 'a, b', 'X-Other': 'c' });
    });

    // Plain JS consumers are not bound by the type contract and nodemailer's own
    // MIME builder tolerates non-string values by coercing them, so the transport
    // should match that behaviour rather than dropping or crashing.
    it('should coerce numeric header values from untyped callers to strings', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const headers = { 'X-Test': 123 } as unknown as Mail.Options['headers'];

      const result = transport.toResendHeaders(headers);

      expect(result).toEqual({ 'X-Test': '123' });
    });

    it('should coerce non-string values in key-value entry arrays to strings', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const headers = [{ key: 'X-Test', value: 123 }] as unknown as Mail.Options['headers'];

      const result = transport.toResendHeaders(headers);

      expect(result).toEqual({ 'X-Test': '123' });
    });

    it('should skip nullish header values from untyped callers', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const headers = {
        'X-Null': null,
        'X-Undefined': undefined,
        'X-Kept': 'value',
      } as unknown as Mail.Options['headers'];

      const result = transport.toResendHeaders(headers);

      expect(result).toEqual({ 'X-Kept': 'value' });
    });

    it('should return undefined when all header values are nullish', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const headers = { 'X-Null': null } as unknown as Mail.Options['headers'];

      const result = transport.toResendHeaders(headers);

      expect(result).toBeUndefined();
    });
  });

  describe('toResendAddresses', () => {
    it('should convert undefined to an array', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const addresses = undefined;

      const result = transport.toResendAddresses(addresses);

      expect(result).toEqual([]);
    });

    it('should convert a string to an array', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const addresses = 'test@example.com';

      const result = transport.toResendAddresses(addresses);

      expect(result).toEqual([addresses]);
    });

    it('should convert a address to an array', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const addresses = { name: 'test', address: 'test@example.com' };

      const result = transport.toResendAddresses(addresses);

      expect(result).toEqual([addresses.address]);
    });

    it('should return an array as is', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const addresses = ['test@example.com', 'test2@example.com'];

      const result = transport.toResendAddresses(addresses);

      expect(result).toEqual(addresses);
    });

    it('should extract addresses from an array of objects', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const addresses = [
        { name: 'test', address: 'test@example.com' },
        { name: 'test2', address: 'test2@example.com' },
      ];

      const result = transport.toResendAddresses(addresses);

      expect(result).toEqual(['test@example.com', 'test2@example.com']);
    });
  });

  describe('toResendFromAddress', () => {
    it('should return an empty string if no address is provided', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const address = undefined;

      const result = transport.toResendFromAddress(address);

      expect(result).toEqual('');
    });

    it('should return a string as is', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const address = 'test@example.com';

      const result = transport.toResendFromAddress(address);

      expect(result).toEqual(address);
    });

    it('should format an object as "name <address>"', () => {
      const transport = new ResendTransport({ apiKey: '[REDACTED]' });

      const address = { name: 'Test User', address: 'test@example.com' };

      const result = transport.toResendFromAddress(address);

      expect(result).toEqual('Test User <test@example.com>');
    });

    describe('toResendAttachments', () => {
      it('should return an empty array if no attachments are provided', () => {
        const transport = new ResendTransport({ apiKey: '[REDACTED]' });

        const attachments = undefined;

        const result = transport.toResendAttachments(attachments);

        expect(result).toEqual([]);
      });

      it('should format an array of string attachments', () => {
        const transport = new ResendTransport({ apiKey: '[REDACTED]' });

        const attachments = [
          {
            filename: 'test.txt',
            content: 'Test content',
          },
          {
            filename: 'test2.txt',
            content: 'Test content 2',
          },
        ];

        const result = transport.toResendAttachments(attachments);

        expect(result).toEqual([
          {
            filename: 'test.txt',
            content: Buffer.from('Test content'),
          },
          {
            filename: 'test2.txt',
            content: Buffer.from('Test content 2'),
          },
        ]);
      });

      it('should format an array of buffer attachments', () => {
        const transport = new ResendTransport({ apiKey: '[REDACTED]' });

        const attachments = [
          {
            filename: 'test.txt',
            content: Buffer.from('Test content'),
          },
          {
            filename: 'test2.txt',
            content: Buffer.from('Test content 2'),
          },
        ];

        const result = transport.toResendAttachments(attachments);

        expect(result).toEqual([
          {
            filename: 'test.txt',
            content: Buffer.from('Test content'),
          },
          {
            filename: 'test2.txt',
            content: Buffer.from('Test content 2'),
          },
        ]);
      });

      it('should throw an error if an attachment is missing a filename', () => {
        const transport = new ResendTransport({ apiKey: '[REDACTED]' });

        const attachments = [
          {
            content: Buffer.from('Test content'),
          },
        ];

        expect(() => transport.toResendAttachments(attachments)).toThrowError(
          'Attachment is missing filename or content',
        );
      });

      it('should throw an error if an attachment is missing contents', () => {
        const transport = new ResendTransport({ apiKey: '[REDACTED]' });

        const attachments = [
          {
            filename: 'test1.txt',
          },
        ];

        expect(() => transport.toResendAttachments(attachments)).toThrowError(
          'Attachment is missing filename or content',
        );
      });

      it('should throw an error if an attachment uses a stream for contents', () => {
        const transport = new ResendTransport({ apiKey: '[REDACTED]' });

        const attachments = [
          {
            filename: 'test1.txt',
            content: Stream.Readable.from('Test content'),
          },
        ];

        expect(() => transport.toResendAttachments(attachments)).toThrowError(
          'Attachment content must be a string or a buffer',
        );
      });
    });
  });
});

import { ResendTransport } from './transport';
import { ResendResponseError, ResendTransportOptions } from './types/transport';

export type { ResendResponseError, ResendTransportOptions };
export { ResendTransport };

// https://github.com/documenso/documenso/blob/9bdff9a61fee6e84e76fdc1bc2fb92529f6a3b79/packages/email/transports/resend.ts
import { type SentMessageInfo, type Transport } from 'nodemailer';
import type Mail from 'nodemailer/lib/mailer';
import type MailMessage from 'nodemailer/lib/mailer/mail-message';
import { Resend } from 'resend';

import { version as VERSION } from '../package.json';
import { ResendTransportOptions } from './types/transport';

export const RESEND_ERROR_CODES_BY_KEY = {
  missing_required_field: 422,
  invalid_idempotency_key: 400,
  invalid_idempotent_request: 409,
  concurrent_idempotent_requests: 409,
  invalid_access: 422,
  invalid_parameter: 422,
  invalid_region: 422,
  rate_limit_exceeded: 429,
  missing_api_key: 401,
  invalid_api_Key: 403,
  invalid_from_address: 403,
  validation_error: 403,
  not_found: 404,
  method_not_allowed: 405,
  application_error: 500,
  internal_server_error: 500,
} as const;

/**
 * Transport for sending email via the Resend SDK.
 */
export class ResendTransport implements Transport<SentMessageInfo> {
  public name = 'ResendMailTransport';
  public version = VERSION;

  private _client: Resend;

  public static makeTransport(options: Partial<ResendTransportOptions>) {
    return new ResendTransport(options);
  }

  constructor(options: Partial<ResendTransportOptions>) {
    const { apiKey = '' } = options;

    this._client = new Resend(apiKey);
  }

  public send(mail: MailMessage, callback: (_err: Error | null, _info: SentMessageInfo) => void) {
    if (!mail.data.to || !mail.data.from) {
      return callback(new Error('Missing required fields "to" or "from"'), null);
    }

    const replyTo = this.toResendAddresses(mail.data.replyTo);

    this._client.emails
      .send({
        subject: mail.data.subject ?? '',
        from: this.toResendFromAddress(mail.data.from),
        to: this.toResendAddresses(mail.data.to),
        cc: this.toResendAddresses(mail.data.cc),
        bcc: this.toResendAddresses(mail.data.bcc),
        replyTo: replyTo.length > 0 ? replyTo : undefined,
        headers: this.toResendHeaders(mail.data.headers),
        html: mail.data.html?.toString() || '',
        text: mail.data.text?.toString() || '',
        attachments: this.toResendAttachments(mail.data.attachments),
      })
      .then((response) => {
        if (response.error) {
          const statusCode = RESEND_ERROR_CODES_BY_KEY[response.error.name] ?? 500;

          throw new Error(`[${statusCode}]: ${response.error.name} ${response.error.message}`);
        }

        callback(null, response.data);
      })
      .catch((error) => {
        callback(error, null);
      });
  }

  public toResendAddresses(addresses: Mail.Options['to']) {
    if (!addresses) {
      return [];
    }

    if (typeof addresses === 'string') {
      return [addresses];
    }

    if (Array.isArray(addresses)) {
      return addresses.map((address) => {
        if (typeof address === 'string') {
          return address;
        }

        return address.address;
      });
    }

    return [addresses.address];
  }

  public toResendFromAddress(address: Mail.Options['from']): string {
    if (!address) {
      return '';
    }

    if (Array.isArray(address)) {
      return this.toResendFromAddress(address[0]);
    }

    if (typeof address === 'string') {
      return address;
    }

    return `${address.name} <${address.address}>`;
  }

  /**
   * Normalizes nodemailer mail headers into the flat `Record<string, string>`
   * shape accepted by the Resend API.
   *
   * Repeated values for the same header key are combined into a single
   * comma-separated value since the API cannot repeat a header key.
   *
   * Values are defensively coerced to strings and nullish values are skipped,
   * mirroring nodemailer's own tolerance for untyped (plain JS) callers.
   *
   * Returns `undefined` when there are no headers so the field is omitted
   * from the API payload entirely.
   */
  public toResendHeaders(headers: Mail.Options['headers']): Record<string, string> | undefined {
    if (!headers) {
      return undefined;
    }

    const normalized: Record<string, string> = {};

    const appendHeader = (key: string, value: unknown) => {
      if (value === null || value === undefined) {
        return;
      }

      const stringValue = String(value);

      normalized[key] = normalized[key] ? `${normalized[key]}, ${stringValue}` : stringValue;
    };

    if (Array.isArray(headers)) {
      for (const { key, value } of headers) {
        appendHeader(key, value);
      }
    } else {
      for (const [key, value] of Object.entries(headers)) {
        if (Array.isArray(value)) {
          for (const item of value) {
            appendHeader(key, item);
          }

          continue;
        }

        if (typeof value === 'object' && value !== null) {
          appendHeader(key, value.value);
          continue;
        }

        appendHeader(key, value);
      }
    }

    if (Object.keys(normalized).length === 0) {
      return undefined;
    }

    return normalized;
  }

  public toResendAttachments(attachments: Mail.Options['attachments']) {
    if (!attachments) {
      return [];
    }

    return attachments.map((attachment) => {
      if (!attachment.filename || !attachment.content) {
        throw new Error('Attachment is missing filename or content');
      }

      if (typeof attachment.content === 'string') {
        return {
          filename: attachment.filename,
          content: Buffer.from(attachment.content),
        };
      }

      if (attachment.content instanceof Buffer) {
        return {
          filename: attachment.filename,
          content: attachment.content,
        };
      }

      throw new Error('Attachment content must be a string or a buffer');
    });
  }
}

export type ResendTransportOptions = {
  apiKey: string;
};

export type ResendResponseError = {
  statusCode: number;
  name: string;
  message: string;
};
